import Script from 'next/script';
import { redirect } from 'next/navigation';
import { createServerSupabase } from '@/lib/supabase/server';

/**
 * لعبة «إكس أو» الذكية — مولّد بنظام رصيد (نفس رصيد ألعاب المليون).
 * البوابة: تسجيل دخول + رصيد ألعاب > 0 (أو أدمِن). الذكاء عبر /api/game-ai،
 * والخصم عبر /api/game-consume عند تشغيل لعبة. المعاينة مجانية. حتى 5 لاعبين.
 */
export const dynamic = 'force-dynamic';

const CSS = "@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;700;800;900&display=swap');\n:root{\n  --sage:#7A9E7E; --sage-dark:#5C7F60; --gold:#C9A84C; --cream:#FAF8F3;\n  --ink:#2E3A2F; --line:#E8E4D8;\n}\n*{margin:0;padding:0;box-sizing:border-box;font-family:'Cairo',sans-serif;-webkit-tap-highlight-color:transparent}\nbody{background:var(--cream);color:var(--ink);min-height:100vh}\nbutton{cursor:pointer;border:none;background:none;font-family:inherit}\n\n/* ===== المولّد ===== */\n.gen-wrap{max-width:680px;margin:0 auto;padding:22px 18px 60px}\n.mg-home{display:inline-flex;align-items:center;gap:6px;color:var(--sage-dark);font-weight:800;font-size:13.5px;text-decoration:none;background:#F0F5F0;border:1.5px solid #DDE8DD;border-radius:12px;padding:9px 16px;margin-bottom:16px;transition:.18s}\n.mg-home:hover{background:#E7F0E8;border-color:var(--sage)}\n.brand{text-align:center;margin-bottom:22px}\n.brand .seed{font-size:44px;line-height:1}\n.brand h1{font-size:26px;font-weight:900;color:var(--sage-dark);margin-top:6px}\n.brand p{color:#7d8a7e;font-size:14px;margin-top:4px}\n.badge{display:inline-block;background:var(--gold);color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:20px;margin-top:8px}\n.cbadge{display:inline-block;margin-top:10px;background:#EAF3EC;color:#3E6B45;font-weight:800;font-size:13px;padding:6px 16px;border-radius:20px;border:1.5px solid #CFE3D2}\n.cbadge.empty{background:#FBEEEC;color:#9C4536;border-color:#E7BBB3}\n.cbadge.admin{background:#FBF3DD;color:#8a6d1f;border-color:#EADFB8}\n.buy-link{display:block;margin:10px auto 0;background:none;border:none;color:var(--sage-dark);font-weight:800;font-size:13px;cursor:pointer;text-decoration:underline}\n\n.card{background:#fff;border:1.5px solid var(--line);border-radius:18px;padding:22px;margin-bottom:16px;box-shadow:0 2px 10px rgba(122,158,126,.07)}\n.card h2{font-size:16px;font-weight:800;color:var(--sage-dark);margin-bottom:12px;display:flex;align-items:center;gap:8px}\n.card h2 .num{background:var(--sage);color:#fff;width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:13px;flex-shrink:0}\n.tabs{display:flex;gap:8px;margin-bottom:14px}\n.tab{flex:1;padding:10px;border:1.5px solid var(--line);border-radius:12px;background:#fff;font-weight:700;font-size:14px;cursor:pointer;color:#8a917f;transition:.2s}\n.tab.on{border-color:var(--sage);background:#F0F5F0;color:var(--sage-dark)}\n.drop{border:2px dashed #C8D4C9;border-radius:14px;padding:26px 16px;text-align:center;cursor:pointer;transition:.2s;background:#FBFCFA}\n.drop:hover,.drop.over{border-color:var(--sage);background:#F0F5F0}\n.drop .ic{font-size:34px}.drop p{font-size:14px;color:#6d7a6e;margin-top:8px;font-weight:500}.drop small{color:#a5aea0;font-size:12px}\n#fileInput{display:none}\n.thumbs{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}\n.thumb{position:relative;width:76px;height:96px;border-radius:10px;overflow:hidden;border:1.5px solid var(--line)}\n.thumb img{width:100%;height:100%;object-fit:cover}\n.thumb .x{position:absolute;top:4px;left:4px;background:rgba(0,0,0,.55);color:#fff;border:none;width:20px;height:20px;border-radius:50%;cursor:pointer;font-size:11px;line-height:1}\ntextarea{width:100%;min-height:150px;border:1.5px solid var(--line);border-radius:14px;padding:14px;font-size:15px;resize:vertical;background:#FBFCFA;color:var(--ink)}\ntextarea:focus{outline:none;border-color:var(--sage)}\n.row{display:flex;gap:12px;flex-wrap:wrap}\n.field{flex:1;min-width:150px}\n.field label{display:block;font-size:13px;font-weight:700;color:#6d7a6e;margin-bottom:6px}\n.field input,.field select{width:100%;padding:11px 12px;border:1.5px solid var(--line);border-radius:12px;font-size:14px;background:#FBFCFA;color:var(--ink)}\n.field input:focus,.field select:focus{outline:none;border-color:var(--sage)}\n.go{width:100%;padding:17px;border:none;border-radius:16px;background:linear-gradient(135deg,var(--sage),var(--sage-dark));color:#fff;font-size:19px;font-weight:900;cursor:pointer;box-shadow:0 6px 18px rgba(92,127,96,.35);transition:.2s;margin-top:4px}\n.go:hover{transform:translateY(-2px)}.go:disabled{opacity:.55;cursor:not-allowed;transform:none}\n.regen{width:100%;padding:12px;border:1.5px solid var(--line);border-radius:14px;background:#fff;color:#6d7a6e;font-weight:700;font-size:14px;cursor:pointer;margin-top:10px}\n.loading{text-align:center;padding:30px 10px;display:none}.loading.show{display:block}\n.spin{width:50px;height:50px;border:5px solid #E4EBE4;border-top-color:var(--sage);border-radius:50%;margin:0 auto 14px;animation:sp 1s linear infinite}\n@keyframes sp{to{transform:rotate(360deg)}}\n.loading .step{font-weight:700;color:var(--sage-dark);font-size:15px;min-height:22px}\n.err{display:none;background:#FBEEEC;border:1.5px solid #E7BBB3;color:#9C4536;border-radius:12px;padding:14px;font-size:14px;font-weight:500;margin-top:12px}\n.err.show{display:block}\n.preview{display:none}.preview.show{display:block}\n.q-item{background:#FBFCFA;border:1.5px solid var(--line);border-radius:12px;padding:12px;margin-bottom:9px}\n.q-item .qt{font-weight:800;font-size:14px;margin-bottom:5px}\n.q-item .ans{font-size:13px;color:var(--sage-dark);font-weight:700}\n.play-btn{width:100%;padding:16px;border:none;border-radius:16px;background:linear-gradient(135deg,var(--gold),#B0913B);color:#fff;font-size:18px;font-weight:900;cursor:pointer;box-shadow:0 6px 18px rgba(201,168,76,.4);margin-top:8px}\n\n/* عدد اللاعبين */\n.pcount{display:flex;gap:8px;margin-top:6px}\n.pcount button{flex:1;padding:12px 0;border:1.5px solid var(--line);border-radius:12px;background:#FBFCFA;font-weight:800;font-size:17px;color:#8a917f;transition:.18s}\n.pcount button.on{border-color:var(--sage);background:var(--sage);color:#fff}\n\n/* نافذة الشراء */\n.buy-ov{position:fixed;inset:0;z-index:300;background:rgba(20,30,25,.55);backdrop-filter:blur(3px);display:none;align-items:center;justify-content:center;padding:20px}\n.buy-ov.show{display:flex}\n.buy-card{background:#fff;border-radius:22px;max-width:400px;width:100%;padding:28px 24px;text-align:center;position:relative;box-shadow:0 20px 60px rgba(0,0,0,.3)}\n.buy-x{position:absolute;top:14px;left:14px;background:#F0F1EC;border:none;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:13px;color:#6d7a6e}\n.buy-card h3{font-size:20px;font-weight:900;color:var(--sage-dark);margin:6px 0 8px}\n.buy-card p{color:#7d8a7e;font-size:14px;line-height:1.7}\n.buy-opts{display:flex;gap:12px;margin:18px 0 6px}\n.buy-opt{flex:1;position:relative;background:#FBFCFA;border:2px solid var(--line);border-radius:16px;padding:16px 10px;display:flex;flex-direction:column;align-items:center;gap:3px}\n.buy-opt b{font-size:15px;color:var(--ink);font-weight:800}.buy-opt .pr{font-size:19px;font-weight:900;color:var(--sage-dark)}.buy-opt small{font-size:11px;color:#a5aea0}\n.buy-opt.best{border-color:var(--gold);background:#FFFDF6}\n.buy-opt.best .tag{position:absolute;top:-11px;right:50%;transform:translateX(50%);background:var(--gold);color:#fff;font-size:10px;font-weight:800;padding:2px 10px;border-radius:20px;white-space:nowrap}\n.buy-note{font-size:12px;color:#a5aea0;margin-top:14px}\n\n/* ===== اللعبة ===== */\n#game{display:none;position:fixed;inset:0;z-index:100;overflow-y:auto;color:#fff;\n  background:radial-gradient(1200px 600px at 50% -10%,#2E5E8E,#123A63 55%,#0C2340 100%)}\n#game.show{display:block}\n.g-inner{max-width:1000px;margin:0 auto;padding:14px 14px 40px;min-height:100vh;display:flex;flex-direction:column}\n.g-top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}\n.g-home{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);color:#fff;width:40px;height:40px;border-radius:50%;font-size:17px;display:flex;align-items:center;justify-content:center;text-decoration:none}\n.g-ttl{font-size:20px;font-weight:900;color:#FCE9A8;text-shadow:0 2px 6px rgba(0,0,0,.4)}\n\n/* إعداد اللاعبين */\n.setup{max-width:520px;margin:auto;background:rgba(255,255,255,.08);border:1.5px solid rgba(255,255,255,.18);border-radius:22px;padding:26px 22px;text-align:center}\n.setup h2{font-size:22px;font-weight:900;color:#FCE9A8;margin-bottom:6px}\n.setup p{color:#CBD9EC;font-size:14px;margin-bottom:16px}\n.pl-list{display:flex;flex-direction:column;gap:12px;margin-bottom:18px}\n.pl-card{background:rgba(255,255,255,.07);border-radius:16px;padding:10px 12px 12px}\n.pl-row{display:flex;align-items:center;gap:10px}\n.pl-row .em{font-size:26px;width:34px;text-align:center}\n.pl-row input{flex:1;background:rgba(255,255,255,.1);border:1.5px solid rgba(255,255,255,.2);border-radius:10px;color:#fff;padding:9px 12px;font-size:15px;font-weight:700}\n.pl-row input::placeholder{color:#9fb3cf}\n.em-pick{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}\n.em-opt{font-size:20px;line-height:1;padding:6px;border-radius:10px;background:rgba(255,255,255,.08);border:2px solid transparent;transition:.14s}\n.em-opt:hover{background:rgba(255,255,255,.16)}\n.em-opt.on{border-color:#F3C64B;background:rgba(243,198,75,.22);box-shadow:0 3px 10px rgba(243,198,75,.35)}\n.em-opt.taken{opacity:.28;cursor:not-allowed;filter:grayscale(.6)}\n.big-btn{display:block;width:100%;padding:15px;border-radius:16px;background:linear-gradient(135deg,#F3C64B,#D9A21B);color:#3A2A00;font-size:19px;font-weight:900;cursor:pointer;box-shadow:0 8px 22px rgba(243,198,75,.4)}\n\n/* منطقة اللعب */\n.play{display:grid;grid-template-columns:1fr 300px;gap:16px;align-items:start}\n@media(max-width:820px){.play{grid-template-columns:1fr}}\n.board{background:linear-gradient(135deg,#0E2C4A,#0A1F38);border:3px solid #D9A21B;border-radius:18px;padding:10px;box-shadow:0 0 30px rgba(0,0,0,.4)}\n.grid{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}\n.cell{position:relative;aspect-ratio:1;border-radius:11px;display:flex;align-items:flex-start;justify-content:flex-start;padding:5px 7px;font-weight:800;font-size:13px;color:#20364d;\n  background:linear-gradient(160deg,#EAF2FB,#CFE0F2)}\n.cell:nth-child(even){background:linear-gradient(160deg,#FBF3DC,#F1E3BE)}\n.cell.finish{background:linear-gradient(160deg,#B7F0C9,#7FD9A0);color:#0b3b22}\n.cell .lad,.cell .snk{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:46px;opacity:.45;pointer-events:none;z-index:1}\n.cell .jump{position:absolute;bottom:4px;left:6px;font-size:12px;font-weight:900;color:#0b3b22;opacity:.9;z-index:2}\n.cell.finish .jump{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:40px;opacity:.8}\n.cell .toks{position:absolute;inset:0;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:1px;pointer-events:none;z-index:3}\n.tok{font-size:19px;filter:drop-shadow(0 2px 2px rgba(0,0,0,.4));transition:transform .2s}\n.cell.pulse{animation:cellpulse .9s ease}\n@keyframes cellpulse{0%,100%{box-shadow:0 0 0 0 rgba(243,198,75,0)}50%{box-shadow:0 0 0 5px rgba(243,198,75,.95),0 0 18px rgba(243,198,75,.6)}}\n\n/* اللوحة الجانبية */\n.side{display:flex;flex-direction:column;gap:14px}\n.turn-card{background:rgba(255,255,255,.09);border:1.5px solid rgba(255,255,255,.2);border-radius:18px;padding:18px;text-align:center}\n.turn-card .who{font-size:20px;font-weight:900;margin-bottom:4px}\n.turn-card .em{font-size:40px}\n.pick-hint{color:#CBD9EC;font-size:13px;font-weight:700;margin-top:10px}\n.colors{display:flex;gap:11px;justify-content:center;margin:12px 0 4px}\n.col{width:48px;height:48px;border-radius:50%;border:3px solid rgba(255,255,255,.6);cursor:pointer;transition:.15s;box-shadow:0 4px 12px rgba(0,0,0,.35)}\n.col:hover:not(:disabled){transform:translateY(-3px) scale(1.1)}\n.col.sel{border-color:#fff;transform:scale(1.15);box-shadow:0 0 16px rgba(255,255,255,.5)}\n.col:disabled{opacity:.35;cursor:default}\n.rolled-show{min-height:38px;font-size:24px;font-weight:900;margin-top:8px;text-shadow:0 2px 4px rgba(0,0,0,.4)}\n.rolled-show b{font-size:36px}\n.standings{background:rgba(255,255,255,.06);border:1.5px solid rgba(255,255,255,.15);border-radius:16px;padding:12px 14px}\n.standings h4{font-size:13px;color:#CBD9EC;margin-bottom:8px;text-align:center;font-weight:800}\n.st-row{display:flex;align-items:center;gap:8px;padding:5px 0;font-weight:800;font-size:14px}\n.st-row .em{font-size:20px}.st-row .nm{flex:1}.st-row .pos{color:#FCE9A8}\n.st-row.active{background:rgba(243,198,75,.15);border-radius:8px;padding:5px 8px}\n\n/* نافذة السؤال */\n.q-ov{position:fixed;inset:0;z-index:200;background:rgba(6,16,30,.86);display:none;align-items:center;justify-content:center;padding:18px}\n.q-ov.show{display:flex}\n.q-card{background:linear-gradient(160deg,#12325A,#0C2340);border:2.5px solid #D9A21B;border-radius:22px;max-width:620px;width:100%;padding:24px;box-shadow:0 20px 60px rgba(0,0,0,.5);color:#fff}\n.q-card .qtext{color:#fff !important}\n.q-card .qhead{text-align:center;color:#FCE9A8;font-weight:800;font-size:15px;margin-bottom:14px}\n.q-card .qtext{font-size:27px;font-weight:900;text-align:center;line-height:1.8;margin-bottom:22px}\n.q-opts{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n@media(max-width:560px){.q-opts{grid-template-columns:1fr}}\n.q-opt{padding:20px;border-radius:14px;background:linear-gradient(180deg,#25379E,#131F6B);border:2px solid rgba(255,255,255,.15);color:#fff;font-weight:800;font-size:21px;text-align:center;cursor:pointer;transition:.15s;min-height:66px;display:flex;align-items:center;justify-content:center}\n.q-opt:hover:not(:disabled){transform:translateY(-2px);border-color:#F3C64B}\n.q-opt.correct{background:linear-gradient(180deg,#1F7A45,#125230)!important;border-color:#4BD98A}\n.q-opt.wrong{background:linear-gradient(180deg,#8C2B25,#5E1B17)!important;border-color:#FF7B6B}\n.q-opt:disabled{cursor:default}\n.q-fb{display:none;margin-top:16px;text-align:center}\n.q-fb.show{display:block}\n.q-fb .h{font-size:20px;font-weight:900;margin-bottom:6px}\n.q-fb .h.ok{color:#4BD98A}.q-fb .h.no{color:#FF7B6B}\n.q-fb .ex{color:#CBD9EC;font-size:14px;line-height:1.7}\n.q-fb button{margin-top:14px;padding:12px 40px;border-radius:40px;background:#F3C64B;color:#3A2A00;font-weight:900;font-size:16px;cursor:pointer}\n\n/* النهاية */\n.win-ov{position:fixed;inset:0;z-index:250;background:rgba(6,16,30,.9);display:none;align-items:center;justify-content:center;padding:20px;text-align:center}\n.win-ov.show{display:flex;flex-direction:column}\n.win-ov .cup{font-size:80px}\n.win-ov h1{font-size:30px;font-weight:900;color:#FCE9A8;margin:10px 0}\n.win-ov .em{font-size:56px;margin:6px}\n.win-ov button{margin-top:16px;padding:14px 40px;border-radius:40px;background:#F3C64B;color:#3A2A00;font-weight:900;font-size:17px;cursor:pointer}\n.win-ov a{margin-top:10px;color:#CBD9EC;text-decoration:underline;font-weight:700}\n.confetti{position:fixed;top:-10px;width:11px;height:15px;z-index:260;pointer-events:none;animation:fall linear forwards}\n@keyframes fall{to{transform:translateY(105vh) rotate(600deg)}}\n.toast{position:fixed;bottom:22px;right:50%;transform:translateX(50%);background:#0b1f38;color:#fff;border-radius:999px;padding:11px 22px;font-weight:800;font-size:14px;box-shadow:0 8px 24px rgba(0,0,0,.4);opacity:0;pointer-events:none;transition:.3s;z-index:400}\n.toast.show{opacity:1;bottom:32px}\n\n/* ===== لوحة إكس أو ===== */\n.xwrap{display:flex;justify-content:center}\n.xboard{background:linear-gradient(135deg,#0E2C4A,#0A1F38);border:3px solid #D9A21B;border-radius:24px;padding:16px;box-shadow:0 0 34px rgba(0,0,0,.45);width:100%;max-width:460px}\n.xgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n.xcell{position:relative;aspect-ratio:1;border-radius:16px;display:flex;align-items:center;justify-content:center;background:linear-gradient(160deg,#EAF2FB,#CFE0F2);cursor:pointer;transition:.16s;box-shadow:inset 0 -3px 8px rgba(0,0,0,.08)}\n.xcell:hover:not(.filled){transform:translateY(-3px);box-shadow:0 8px 20px rgba(243,198,75,.45);background:linear-gradient(160deg,#FBF3DC,#F1E3BE)}\n.xcell.filled{cursor:default}\n.xcell .mark{font-size:74px;line-height:1;filter:drop-shadow(0 3px 4px rgba(0,0,0,.25));animation:pop .3s ease}\n@keyframes pop{0%{transform:scale(0)}70%{transform:scale(1.18)}100%{transform:scale(1)}}\n.xcell.win{background:linear-gradient(160deg,#B7F0C9,#7FD9A0)!important;animation:xwin .8s ease infinite}\n@keyframes xwin{0%,100%{box-shadow:0 0 0 0 rgba(75,217,138,0)}50%{box-shadow:0 0 0 5px rgba(75,217,138,.9),0 0 20px rgba(75,217,138,.6)}}\n/* بطاقات الفرق الجانبية */\n.tm-row{display:flex;align-items:center;gap:9px;padding:8px 10px;border-radius:12px;font-weight:800;font-size:15px;background:rgba(255,255,255,.05)}\n.tm-row .mk{font-size:24px}.tm-row .nm{flex:1}\n.tm-row.active{background:rgba(243,198,75,.16);border:1.5px solid rgba(243,198,75,.5)}\n@media(max-width:820px){.xcell .mark{font-size:58px}}\n\n/* ===== وضع كتابة الأسئلة يدويًا ===== */\n.man-note{background:#FBF3DD;border:1.5px solid #EADFB8;color:#8a6d1f;font-size:13px;font-weight:700;padding:10px 12px;border-radius:12px;margin-bottom:12px;line-height:1.7}\n.man-form{display:flex;flex-direction:column;gap:9px}\n.man-in{width:100%;padding:11px 13px;border:1.5px solid #E8E4D8;border-radius:12px;font-size:14px;background:#FBFCFA;color:#2E3A2F}\n.man-in:focus{outline:none;border-color:#7A9E7E}\n.man-opt{display:flex;align-items:center;gap:9px}\n.man-opt input[type=radio]{width:22px;height:22px;flex-shrink:0;accent-color:#5C7F60;cursor:pointer}\n.man-opt .man-in{flex:1}\n.man-hint{font-size:12.5px;color:#a5aea0}\n.man-add{background:#F0F5F0;border:1.5px solid #DDE8DD;color:#5C7F60;font-weight:800;font-size:14px;padding:12px;border-radius:12px;cursor:pointer}\n.man-list{margin-top:12px;display:flex;flex-direction:column;gap:8px}\n.man-q{background:#FBFCFA;border:1.5px solid #E8E4D8;border-radius:12px;padding:10px 12px;display:flex;gap:8px;align-items:flex-start}\n.man-q .mqt{flex:1;font-size:13.5px;font-weight:700;color:#2E3A2F}\n.man-q .mqa{font-size:12.5px;color:#5C7F60;font-weight:700;margin-top:3px}\n.man-q .mdel{background:none;border:none;color:#c9908a;font-size:15px;cursor:pointer;flex-shrink:0}\n.man-use{width:100%;padding:15px;border:none;border-radius:14px;background:linear-gradient(135deg,#C9A84C,#B0913B);color:#fff;font-size:16px;font-weight:900;cursor:pointer;margin-top:12px}";
const BODY = "<!-- ============ المولّد ============ -->\n<div class=\"gen-wrap\" id=\"genWrap\">\n  <a href=\"/\" class=\"mg-home\">← رجوع لمنصة غراس</a>\n  <div class=\"brand\">\n    <div class=\"seed\">⭕❌</div>\n    <h1>إكس أو الذكية</h1>\n    <p>صوّري الدرس… والذكاء يبني لعبة إكس أو تفاعلية</p>\n    <span class=\"badge\">أداة غراس المعلم</span>\n    <div id=\"creditBadge\" class=\"cbadge\"></div>\n    <button class=\"buy-link\" onclick=\"showBuy()\">＋ شراء ألعاب</button>\n  </div>\n\n  <div class=\"card\">\n    <h2><span class=\"num\">١</span> محتوى الدرس</h2>\n    <div class=\"tabs\">\n      <button class=\"tab on\" id=\"tabImg\" onclick=\"switchTab('img')\">📷 صور الدرس</button>\n      <button class=\"tab\" id=\"tabTxt\" onclick=\"switchTab('txt')\">📝 نص الدرس</button>\n      <button class=\"tab\" id=\"tabMan\" onclick=\"switchTab('man')\">✍️ اكتب أسئلتك</button>\n    </div>\n    <div id=\"paneImg\">\n      <label class=\"drop\" id=\"drop\" for=\"fileInput\" style=\"display:block\">\n        <div class=\"ic\">📄</div>\n        <p>اضغطي هنا لرفع صور صفحات الدرس</p>\n        <small>أو صوّريها بالكاميرا مباشرة — حتى ٥ صور</small>\n      </label>\n      <input type=\"file\" id=\"fileInput\" accept=\"image/*\" multiple>\n      <div class=\"thumbs\" id=\"thumbs\"></div>\n    </div>\n    <div id=\"paneTxt\" style=\"display:none\">\n      <textarea id=\"lessonText\" placeholder=\"الصقي نص الدرس هنا…\"></textarea>\n    </div>\n    <div id=\"paneMan\" style=\"display:none\">\n      <div class=\"man-note\">✍️ اكتبي أسئلتك كما تريدين — تُستخدم <b>حرفيًا بدون أي تعديل</b> من الذكاء.</div>\n      <div class=\"man-form\">\n        <input id=\"mq\" class=\"man-in\" placeholder=\"اكتبي نص السؤال…\">\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"0\" checked title=\"الصحيحة\"><input id=\"mo0\" class=\"man-in\" placeholder=\"الخيار الأول\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"1\" title=\"الصحيحة\"><input id=\"mo1\" class=\"man-in\" placeholder=\"الخيار الثاني\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"2\" title=\"الصحيحة\"><input id=\"mo2\" class=\"man-in\" placeholder=\"الخيار الثالث\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"3\" title=\"الصحيحة\"><input id=\"mo3\" class=\"man-in\" placeholder=\"الخيار الرابع\"></div>\n        <div class=\"man-hint\">حدّدي الدائرة أمام الإجابة الصحيحة 👆 ثم أضيفي السؤال</div>\n        <button class=\"man-add\" onclick=\"addManualQ()\">➕ أضيفي السؤال</button>\n      </div>\n      <div id=\"manList\" class=\"man-list\"></div>\n      <button class=\"man-use\" id=\"manUseBtn\" onclick=\"useManual()\" style=\"display:none\">▶️ استخدمي أسئلتي</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2><span class=\"num\">٢</span> إعدادات اللعبة</h2>\n    <div class=\"row\">\n      <div class=\"field\"><label>اسم الدرس (اختياري)</label><input id=\"lessonName\" placeholder=\"مثال: أركان الإسلام\"></div>\n      <div class=\"field\"><label>الصف</label>\n        <select id=\"gradeSel\">\n          <option value=\"الأول\">الأول</option><option value=\"الثاني\">الثاني</option><option value=\"الثالث\">الثالث</option>\n          <option value=\"الرابع\">الرابع</option><option value=\"الخامس\" selected>الخامس</option><option value=\"السادس\">السادس</option>\n          <option value=\"السابع\">السابع</option><option value=\"الثامن\">الثامن</option><option value=\"التاسع\">التاسع</option>\n        </select></div>\n      <div class=\"field\"><label>الفئة</label>\n        <select id=\"genderSel\"><option value=\"بنات\" selected>بنات</option><option value=\"بنين\">بنين</option></select></div>\n    </div>\n    <div class=\"field\" style=\"margin-top:12px\"><label>الفرق</label>\n      <div class=\"hint\" style=\"font-size:13px;color:#7d8a7e;margin-top:2px\">فريقان: ❌ و ⭕ — تقدرين تعدّلين الأسماء والعلامات قبل بدء اللعب</div>\n    </div>\n  </div>\n\n  <button class=\"go\" id=\"goBtn\" onclick=\"generate()\">✨ إنشاء اللعبة</button>\n  <button class=\"regen\" onclick=\"demoPlay()\">👀 معاينة شكل اللعبة (أسئلة تجريبية)</button>\n\n  <div class=\"loading\" id=\"loading\"><div class=\"spin\"></div><div class=\"step\" id=\"stepText\">جارٍ قراءة الدرس…</div></div>\n  <div class=\"err\" id=\"errBox\"></div>\n\n  <div class=\"card preview\" id=\"preview\">\n    <h2><span class=\"num\">٣</span> الأسئلة المولّدة <span id=\"qCount\" style=\"color:#a5aea0;font-weight:500;font-size:13px\"></span></h2>\n    <div id=\"qList\"></div>\n    <button class=\"play-btn\" onclick=\"openGame()\">🎲 تشغيل اللعبة</button>\n    <button class=\"regen\" onclick=\"generate()\">🔄 إعادة توليد الأسئلة</button>\n  </div>\n</div>\n\n<!-- ============ اللعبة ============ -->\n<div id=\"game\">\n  <div class=\"g-inner\" id=\"gInner\"></div>\n</div>\n<div class=\"q-ov\" id=\"qOv\"><div class=\"q-card\" id=\"qCard\"></div></div>\n<div class=\"win-ov\" id=\"winOv\"></div>\n<div class=\"toast\" id=\"toast\"></div>";
const JS = "/* ---------- الحالة ---------- */\nlet images=[], questions=[], playerCount=2, DEMO=false, COMMITTED=false;\nconst IS_ADMIN=!!(window.__IS_ADMIN);\nlet CREDITS=(typeof window.__GAME_CREDITS==='number')?window.__GAME_CREDITS:0;\nconst AR=n=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n\n/* ---------- مؤثرات صوتية ---------- */\nlet AC=null;\nfunction ac(){if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();return AC}\nfunction tone(freq,dur,type,vol,when,slide){type=type||'sine';vol=vol||.18;when=when||0;\n  try{const c=ac(),o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,c.currentTime+when);\n  if(slide)o.frequency.exponentialRampToValueAtTime(slide,c.currentTime+when+dur);\n  g.gain.setValueAtTime(vol,c.currentTime+when);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+when+dur);\n  o.connect(g);g.connect(c.destination);o.start(c.currentTime+when);o.stop(c.currentTime+when+dur+.05);}catch(_){}}\nconst SFX={\n  pick(){tone(523,.12,'triangle',.18);tone(660,.14,'triangle',.16,.08)},\n  step(){tone(760,.07,'square',.09)},\n  correct(){tone(523,.13,'triangle',.2);tone(659,.13,'triangle',.2,.11);tone(784,.3,'triangle',.22,.22)},\n  wrong(){tone(220,.28,'sawtooth',.16,0,110)},\n  climb(){[440,554,659,880,1047].forEach((f,i)=>tone(f,.12,'triangle',.18,i*.08))},\n  slide(){tone(720,.5,'sawtooth',.16,0,150)},\n  win(){[523,659,784,1047,784,1047,1319].forEach((f,i)=>tone(f,.22,'triangle',.2,i*.13))}\n};\n\n/* إكس أو — لوحة ٣×٣ */\nconst MARKS_POOL=['❌','⭕','⭐','❤️','🔷','🌙','🔶','💚'];\nconst TEAM_DEF=[{mark:'❌',color:'#E24A3B'},{mark:'⭕',color:'#2E7DD1'}];\nconst WIN_LINES=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];\nlet LNAME='اللعبة';\nlet teams=[], turn=0, awaiting=false, qIndex=0, pendingCell=-1, board=[], winLine=null;\n\n/* ---------- التبويبات والصور ---------- */\nfunction switchTab(t){\n  document.getElementById('tabImg').classList.toggle('on',t==='img');\n  document.getElementById('tabTxt').classList.toggle('on',t==='txt');\n  document.getElementById('tabMan').classList.toggle('on',t==='man');\n  document.getElementById('paneImg').style.display=t==='img'?'':'none';\n  document.getElementById('paneTxt').style.display=t==='txt'?'':'none';\n  document.getElementById('paneMan').style.display=t==='man'?'':'none';\n  document.getElementById('goBtn').style.display=t==='man'?'none':'';\n}\nfunction pickCount(btn){\n  document.querySelectorAll('#pcount button').forEach(b=>b.classList.remove('on'));\n  btn.classList.add('on'); playerCount=+btn.dataset.n;\n}\ndocument.getElementById('fileInput').addEventListener('change',e=>addFiles(e.target.files));\nconst drop=document.getElementById('drop');\ndrop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('over')});\ndrop.addEventListener('dragleave',()=>drop.classList.remove('over'));\ndrop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('over');addFiles(e.dataTransfer.files)});\nfunction addFiles(files){\n  [...files].slice(0,5-images.length).forEach(f=>{\n    if(!f.type.startsWith('image/'))return;\n    const r=new FileReader();\n    r.onload=()=>{\n      const img=new Image();\n      img.onload=()=>{\n        try{const MAX=900;let w=img.width,h=img.height;\n          if(Math.max(w,h)>MAX){const s=MAX/Math.max(w,h);w=Math.round(w*s);h=Math.round(h*s)}\n          const cv=document.createElement('canvas');cv.width=w;cv.height=h;\n          cv.getContext('2d').drawImage(img,0,0,w,h);\n          const url=cv.toDataURL('image/jpeg',0.65);\n          images.push({data:url.split(',')[1],type:'image/jpeg',url});\n        }catch(e){images.push({data:r.result.split(',')[1],type:f.type,url:r.result});}\n        renderThumbs();\n      };\n      img.onerror=()=>{images.push({data:r.result.split(',')[1],type:f.type,url:r.result});renderThumbs();};\n      img.src=r.result;\n    };\n    r.readAsDataURL(f);\n  });\n  document.getElementById('fileInput').value='';\n}\nfunction renderThumbs(){\n  document.getElementById('thumbs').innerHTML=images.map((im,i)=>\n    `<div class=\"thumb\"><img src=\"${im.url}\"><button class=\"x\" onclick=\"images.splice(${i},1);renderThumbs()\">✕</button></div>`).join('');\n}\n\n/* ---------- التوليد ---------- */\nconst STEPS=['جارٍ قراءة صفحات الدرس… 📖','جارٍ استخراج المفاهيم… 🔍','جارٍ بناء الأسئلة… 🧠','جارٍ تجهيز اللعبة… 🎲'];\nasync function generate(){\n  DEMO=false;COMMITTED=false;\n  const text=document.getElementById('lessonText').value.trim();\n  if(images.length===0 && !text){showErr('ارفعي صور الدرس أو الصقي النص أولاً 🌱');return}\n  hideErr();\n  document.getElementById('preview').classList.remove('show');\n  document.getElementById('goBtn').disabled=true;\n  document.getElementById('loading').classList.add('show');\n  let si=0;const st=document.getElementById('stepText');st.textContent=STEPS[0];\n  const stepInt=setInterval(()=>{si=(si+1)%STEPS.length;st.textContent=STEPS[si]},3200);\n  const grade=document.getElementById('gradeSel').value;\n  const gender=document.getElementById('genderSel').value;\n  const lname=document.getElementById('lessonName').value.trim();\n  const genderNote=gender==='بنات'?'خاطب الطالبات بصيغة المؤنث':'خاطب الطلاب بصيغة المذكر';\n  const prompt=`أنت خبير مناهج كويتي. أمامك محتوى درس للصف ${grade}${lname?` بعنوان \"${lname}\"`:''}.\nولّد 10 أسئلة اختيار من متعدد متدرّجة من السهل إلى الصعب، مستخرجة من محتوى الدرس فقط.\nشروط: ${genderNote}. 4 خيارات، إجابة واحدة صحيحة، مشتتات خاطئة قطعاً. الشرح سطر واحد قصير جداً. الآيات والأحاديث تُنقل بدقة.\nأجب بـ JSON مضغوط فقط بلا markdown:\n{\"questions\":[{\"q\":\"..\",\"options\":[\"..\",\"..\",\"..\",\"..\"],\"correct\":0,\"explain\":\"..\"}]}\n${text?`\\nنص الدرس:\\n${text}`:''}`;\n  async function callAPI(imgSet){\n    const imgs=imgSet||images;\n    const content=[...imgs.map(im=>({type:'image',source:{type:'base64',media_type:im.type,data:im.data}})),{type:'text',text:prompt}];\n    const res=await fetch('/api/game-ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({max_tokens:2500,messages:[{role:'user',content}]})});\n    const data=await res.json();\n    if(data.error)throw new Error(data.error.message||'خطأ في الخدمة');\n    const raw=(data.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('\\n');\n    const clean=raw.replace(/```json|```/g,'').trim();\n    const slice=clean.slice(clean.indexOf('{'),clean.lastIndexOf('}')+1);\n    let parsed;\n    try{parsed=JSON.parse(slice)}catch(_){const cut=slice.lastIndexOf('},');if(cut>0)parsed=JSON.parse(slice.slice(0,cut+1)+']}');else throw new Error('تعذّر قراءة النتيجة');}\n    return parsed;\n  }\n  async function tryGen(){try{return await callAPI()}catch(e){if(images.length>1){return await callAPI([images[0]])}throw e;}}\n  try{\n    const p=await tryGen();\n    questions=(p.questions||[]).slice(0,10);\n    if(questions.length<3)throw new Error('لم يتمكن النظام من استخراج أسئلة كافية — جرّبي صوراً أوضح');\n    renderPreview();\n    try{if(window.GHLib)GHLib.save();}catch(_){}\n  }catch(e){showErr('تعذّر توليد الأسئلة: '+e.message);}\n  finally{clearInterval(stepInt);document.getElementById('loading').classList.remove('show');document.getElementById('goBtn').disabled=false;}\n}\nfunction showErr(m){const b=document.getElementById('errBox');b.textContent=m;b.classList.add('show')}\nfunction hideErr(){document.getElementById('errBox').classList.remove('show')}\nfunction renderPreview(){\n  document.getElementById('qCount').textContent=`(${AR(questions.length)} أسئلة)`;\n  try{saveGame();}catch(_){}\n  document.getElementById('qList').innerHTML=questions.map((q,i)=>\n    `<div class=\"q-item\"><div class=\"qt\">${AR(i+1)}. ${q.q}</div><div class=\"ans\">✔ ${q.options[q.correct]}</div></div>`).join('');\n  document.getElementById('preview').classList.add('show');\n  try{document.getElementById('preview').scrollIntoView({behavior:'smooth'})}catch(_){}\n}\n\n/* ---------- كتابة الأسئلة يدويًا + الحفظ التلقائي ---------- */\nlet manualQs=[];\nconst GLS_KEY='ghiras_xo_game_v1';\nfunction addManualQ(){\n  const q=(document.getElementById('mq').value||'').trim();\n  const opts=[0,1,2,3].map(i=>(document.getElementById('mo'+i).value||'').trim());\n  if(!q){showErr('اكتبي نص السؤال أولًا');return;}\n  if(opts.some(o=>!o)){showErr('اكتبي الخيارات الأربعة كاملة');return;}\n  const cor=+((document.querySelector('input[name=mcorrect]:checked')||{value:'0'}).value);\n  manualQs.push({q,options:opts,correct:cor,explain:''});\n  document.getElementById('mq').value=''; [0,1,2,3].forEach(i=>document.getElementById('mo'+i).value='');\n  const r0=document.querySelector('input[name=mcorrect][value=\"0\"]'); if(r0)r0.checked=true;\n  hideErr(); renderManList();\n}\nfunction delManualQ(i){ manualQs.splice(i,1); renderManList(); }\nfunction renderManList(){\n  const el=document.getElementById('manList');\n  el.innerHTML=manualQs.map((q,i)=>`<div class=\"man-q\"><div class=\"mqt\">${AR(i+1)}. ${q.q}<div class=\"mqa\">✔ ${q.options[q.correct]}</div></div><button class=\"mdel\" onclick=\"delManualQ(${i})\">✕</button></div>`).join('');\n  document.getElementById('manUseBtn').style.display=manualQs.length?'block':'none';\n}\nfunction useManual(){\n  if(manualQs.length<1){showErr('أضيفي سؤالًا واحدًا على الأقل');return;}\n  questions=manualQs.map(q=>({...q,options:[...q.options]}));\n  renderPreview();\n  try{if(window.GHLib)GHLib.save();}catch(_){}\n}\nfunction saveGame(){try{localStorage.setItem(GLS_KEY,JSON.stringify({questions,lesson:(document.getElementById('lessonName').value||'').trim(),committed:COMMITTED,ts:Date.now()}));}catch(e){}}\nfunction loadSaved(){try{const r=localStorage.getItem(GLS_KEY);if(!r)return;const d=JSON.parse(r);if(d&&Array.isArray(d.questions)&&d.questions.length){questions=d.questions;if(d.lesson)document.getElementById('lessonName').value=d.lesson;COMMITTED=!!d.committed;renderPreview();const qc=document.getElementById('qCount');if(qc)qc.textContent=qc.textContent+' — محفوظة ✅';}}catch(e){}}\n\n\n/* ---------- خطافات مكتبة «ألعابي المحفوظة» ---------- */\nwindow.__libGetData=function(){\n  if(!questions||!questions.length)return null;\n  const lesson=(document.getElementById('lessonName').value||'').trim();\n  return { title: lesson||'إكس أو',\n           data:{ questions, lesson, committed:(typeof COMMITTED!=='undefined'&&COMMITTED) } };\n};\nwindow.__libApply=function(d){\n  if(!d||!Array.isArray(d.questions))return;\n  questions=d.questions.map(q=>({...q,options:Array.isArray(q.options)?[...q.options]:q.options}));\n  const el=document.getElementById('lessonName'); if(el&&d.lesson)el.value=d.lesson;\n  COMMITTED=!!d.committed;\n  renderPreview();\n};\nfunction demoPlay(){\n  questions=[\n    {q:'كم عدد أركان الإسلام؟',options:['خمسة','ثلاثة','سبعة','أربعة'],correct:0,explain:'أركان الإسلام خمسة.'},\n    {q:'ما أول أركان الإسلام؟',options:['الشهادتان','الصلاة','الزكاة','الصوم'],correct:0,explain:'أول الأركان الشهادتان.'},\n    {q:'كم عدد الصلوات المفروضة في اليوم؟',options:['خمس','ثلاث','سبع','أربع'],correct:0,explain:'الصلوات المفروضة خمس.'},\n    {q:'في أي شهر نصوم؟',options:['رمضان','شعبان','رجب','محرم'],correct:0,explain:'نصوم شهر رمضان.'},\n    {q:'إلى أين يكون الحج؟',options:['مكة المكرمة','المدينة','القدس','الطائف'],correct:0,explain:'الحج إلى بيت الله الحرام في مكة.'},\n    {q:'ما الركن المالي في الإسلام؟',options:['الزكاة','الصلاة','الصوم','الحج'],correct:0,explain:'الزكاة ركن مالي.'},\n    {q:'كم مرة نقول الشهادة لندخل الإسلام؟',options:['مرة بصدق','خمس مرات','ثلاث','عشر'],correct:0,explain:'ينطق بها بصدق ويقين.'},\n    {q:'متى فُرض الصيام؟',options:['في رمضان','في شعبان','في شوال','في ذي الحجة'],correct:0,explain:'الصيام في رمضان.'},\n    {q:'ما جزاء من صام رمضان إيماناً؟',options:['غُفر له','لا شيء','يعاقب','ينقص أجره'],correct:0,explain:'غُفر له ما تقدّم من ذنبه.'},\n    {q:'أين تُؤدى الصلاة جماعة غالباً؟',options:['في المسجد','في السوق','في المدرسة فقط','في البيت فقط'],correct:0,explain:'الجماعة في المسجد.'}\n  ];\n  document.getElementById('lessonName').value=document.getElementById('lessonName').value.trim()||'أركان الإسلام';\n  DEMO=true;COMMITTED=false;openGame();\n}\n\n/* ---------- نظام الرصيد ---------- */\nasync function consumeCredit(){\n  if(IS_ADMIN) return {ok:true,unlimited:true};\n  try{const r=await fetch('/api/game-consume',{method:'POST'});const d=await r.json();\n    if(!d.ok) return {ok:false,error:d.error};\n    return {ok:true,remaining:d.remaining,unlimited:d.unlimited};}catch(_){return {ok:false,error:'net'};}\n}\nfunction updateCreditBadge(){\n  const el=document.getElementById('creditBadge'); if(!el)return;\n  if(IS_ADMIN){el.innerHTML='♾️ رصيد غير محدود';el.className='cbadge admin';return;}\n  el.innerHTML='🎟️ رصيدك: <b>'+AR(CREDITS)+'</b> '+(CREDITS===1?'لعبة':'ألعاب');\n  el.className='cbadge'+(CREDITS<=0?' empty':'');\n}\nfunction showBuy(){\n  let m=document.getElementById('buyModal');\n  if(!m){m=document.createElement('div');m.id='buyModal';m.className='buy-ov';\n    m.innerHTML=`<div class=\"buy-card\"><button class=\"buy-x\" onclick=\"closeBuy()\">✕</button>\n      <div style=\"font-size:40px\">🎟️</div><h3>خلص رصيد الألعاب</h3>\n      <p>لإنشاء لعبة جديدة من درسك، اختر باقة الرصيد المناسبة:</p>\n      <div class=\"buy-opts\">\n        <button class=\"buy-opt\" onclick=\"buyGame(3)\"><b>٣ ألعاب</b><span class=\"pr\">٢ د.ك</span><small>٠.٦٧ للعبة</small></button>\n        <button class=\"buy-opt best\" onclick=\"buyGame(10)\"><span class=\"tag\">الأوفر</span><b>١٠ ألعاب</b><span class=\"pr\">٥ د.ك</span><small>٠.٥ للعبة</small></button>\n      </div>\n      <p class=\"buy-note\">التفعيل حاليًا عبر إدارة غراس المعلم، والدفع الإلكتروني قريبًا 🌱</p></div>`;\n    document.body.appendChild(m);\n    m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('show')});\n  }\n  m.classList.add('show');\n}\nfunction closeBuy(){const m=document.getElementById('buyModal');if(m)m.classList.remove('show')}\nfunction buyGame(n){closeBuy();alert(n===3?'🎟️ لشراء ٣ ألعاب (٢ د.ك): تواصلي مع إدارة غراس المعلم.':'🎟️ لشراء باقة ١٠ ألعاب (٥ د.ك): تواصلي مع إدارة غراس المعلم.');}\n\nfunction toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),1800);}\n\n/* ---------- بدء اللعبة: شاشة إعداد اللاعبين ---------- */\nasync function openGame(){\n  if(!DEMO && !COMMITTED){\n    const c=await consumeCredit();\n    if(!c.ok){showBuy();return;}\n    COMMITTED=true;\n    if(!c.unlimited && typeof c.remaining==='number')CREDITS=c.remaining;\n    updateCreditBadge();\n    try{saveGame();}catch(_){}\n    try{if(window.GHLib){GHLib.commitSave();}}catch(_){}\n  }\n  document.getElementById('game').classList.add('show');\n  document.body.style.overflow='hidden';\n  teams=TEAM_DEF.map((t,i)=>({...t, name:'الفريق '+AR(i+1)}));\n  LNAME=document.getElementById('lessonName').value.trim()||'اللعبة';\n  renderSetup();\n}\n\n// اختيار علامة لكل فريق — يمنع تكرار نفس العلامة\nfunction pickMark(i,mk){\n  if(teams.some((t,j)=>j!==i && t.mark===mk)) return;\n  teams[i].mark=mk;\n  renderSetup();\n}\nfunction renderSetup(){\n  document.getElementById('gInner').innerHTML=`\n    <div class=\"g-top\">\n      <a href=\"/\" class=\"g-home\" title=\"رجوع للمنصة\">🏠</a>\n      <div class=\"g-ttl\">⭕❌ إكس أو — ${LNAME}</div>\n      <button class=\"g-home\" onclick=\"closeGame()\" title=\"خروج\">✕</button>\n    </div>\n    <div class=\"setup\">\n      <h2>إعداد الفريقين</h2>\n      <p>عدّلي اسم كل فريق واختاري علامته، ثم ابدئي 🎯</p>\n      <div class=\"pl-list\">${teams.map((t,i)=>\n        `<div class=\"pl-card\">\n           <div class=\"pl-row\"><span class=\"em\">${t.mark}</span><input value=\"${t.name}\" oninput=\"teams[${i}].name=this.value\" maxlength=\"18\"></div>\n           <div class=\"em-pick\">${MARKS_POOL.map(mk=>{\n             const taken=teams.some((q,j)=>j!==i && q.mark===mk);\n             const on=t.mark===mk;\n             return `<button type=\"button\" class=\"em-opt${on?' on':''}${taken?' taken':''}\" ${taken?'disabled':''} onclick=\"pickMark(${i},'${mk}')\">${mk}</button>`;\n           }).join('')}</div>\n         </div>`).join('')}</div>\n      <button class=\"big-btn\" onclick=\"startPlay()\">🚀 ابدأ اللعب</button>\n    </div>`;\n}\nfunction closeGame(){document.getElementById('game').classList.remove('show');document.body.style.overflow='';}\n\n/* ---------- منطق إكس أو ---------- */\nfunction startPlay(){turn=0;qIndex=0;awaiting=false;pendingCell=-1;winLine=null;board=Array(9).fill(null);renderBoard();}\n\nfunction boardCellsHTML(){\n  let out='';\n  for(let i=0;i<9;i++){\n    const v=board[i];\n    const filled=v!==null;\n    const win=winLine&&winLine.indexOf(i)>=0;\n    out+=`<div class=\"xcell${filled?' filled':''}${win?' win':''}\" ${filled?'':`onclick=\"pickCell(${i})\"`}>${filled?`<span class=\"mark\">${teams[v].mark}</span>`:''}</div>`;\n  }\n  return out;\n}\nfunction repaintBoard(){const g=document.querySelector('.xgrid');if(g)g.innerHTML=boardCellsHTML();}\n\nfunction renderBoard(){\n  const cur=teams[turn];\n  const left=board.filter(v=>v===null).length;\n  const tlist=teams.map((t,i)=>`<div class=\"tm-row ${i===turn?'active':''}\"><span class=\"mk\">${t.mark}</span><span class=\"nm\" style=\"color:${i===turn?'#FCE9A8':'#CBD9EC'}\">${t.name}</span></div>`).join('');\n  document.getElementById('gInner').innerHTML=`\n    <div class=\"g-top\">\n      <a href=\"/\" class=\"g-home\" title=\"رجوع للمنصة\">🏠</a>\n      <div class=\"g-ttl\">⭕❌ إكس أو — ${LNAME}</div>\n      <button class=\"g-home\" onclick=\"closeGame()\" title=\"خروج\">✕</button>\n    </div>\n    <div class=\"play\">\n      <div class=\"xwrap\"><div class=\"xboard\"><div class=\"xgrid\">${boardCellsHTML()}</div></div></div>\n      <div class=\"side\">\n        <div class=\"turn-card\">\n          <div class=\"em\">${cur.mark}</div>\n          <div class=\"who\" style=\"color:${cur.color}\">دور ${cur.name}</div>\n          <div class=\"pick-hint\">اختاري خانة فارغة على اللوحة 👆<br>جاوبي صح لتضعي علامتك</div>\n        </div>\n        <div class=\"standings\"><h4>الفريقان</h4>${tlist}</div>\n        <div class=\"standings\" style=\"text-align:center\"><h4>الخانات المتبقية</h4><div style=\"font-size:26px;font-weight:900;color:#FCE9A8\">${AR(left)}</div></div>\n      </div>\n    </div>`;\n}\n\nfunction pickCell(i){\n  if(awaiting || board[i]!==null) return;\n  awaiting=true; pendingCell=i;\n  askQuestion();\n}\n\nfunction askQuestion(){\n  const q=questions[qIndex%questions.length]; qIndex++;\n  const idx=[0,1,2,3].sort(()=>Math.random()-.5);\n  const opts=idx.map(i=>q.options[i]); const correct=idx.indexOf(q.correct);\n  const cur=teams[turn];\n  document.getElementById('qCard').innerHTML=`\n    <div class=\"qhead\">دور ${cur.name} ${cur.mark} — جاوبي صح لتضعي علامتك!</div>\n    <div class=\"qtext\">${q.q}</div>\n    <div class=\"q-opts\" id=\"qOpts\">${opts.map((o,i)=>`<button class=\"q-opt\" data-i=\"${i}\" onclick=\"answerQ(${i},${correct})\">${o}</button>`).join('')}</div>\n    <div class=\"q-fb\" id=\"qFb\"></div>`;\n  document.getElementById('qOv').classList.add('show');\n}\nfunction answerQ(i,correct){\n  document.querySelectorAll('.q-opt').forEach(b=>b.disabled=true);\n  const ok=i===correct;\n  ok?SFX.correct():SFX.wrong();\n  document.querySelector(`.q-opt[data-i=\"${i}\"]`).classList.add(ok?'correct':'wrong');\n  if(!ok)document.querySelector(`.q-opt[data-i=\"${correct}\"]`).classList.add('correct');\n  const q=questions[(qIndex-1)%questions.length];\n  const cur=teams[turn];\n  const fb=document.getElementById('qFb');\n  fb.innerHTML=`<div class=\"h ${ok?'ok':'no'}\">${ok?'✔️ صحيحة — علامة '+cur.mark+' على اللوحة!':'❌ غير صحيحة — الدور ينتقل'}</div>\n    <div class=\"ex\">${q.explain||''}</div>\n    <button onclick=\"resolvePlace(${ok?1:0})\">${ok?'ضع العلامة ✏️':'الدور التالي ➡️'}</button>`;\n  fb.classList.add('show');\n}\nfunction resolvePlace(ok){\n  document.getElementById('qOv').classList.remove('show');\n  if(ok){\n    board[pendingCell]=turn;\n    const line=winnerLine(turn);\n    if(line){winLine=line;repaintBoard();return winGame(teams[turn]);}\n    if(board.every(v=>v!==null)){repaintBoard();return drawGame();}\n  }\n  pendingCell=-1;\n  turn=(turn+1)%teams.length;\n  awaiting=false;\n  renderBoard();\n}\nfunction winnerLine(t){\n  for(const L of WIN_LINES){if(L.every(i=>board[i]===t))return L;}\n  return null;\n}\n\nfunction winGame(t){\n  confetti(); SFX.win();\n  document.getElementById('winOv').innerHTML=`\n    <div class=\"cup\">🏆</div>\n    <div class=\"em\">${t.mark}</div>\n    <h1>مبروك ${t.name}!</h1>\n    <p style=\"color:#CBD9EC;font-weight:700\">جمع ثلاثة على خط وفاز 🎉</p>\n    <button onclick=\"document.getElementById('winOv').classList.remove('show');startPlay()\">🔄 العب مرة أخرى</button>\n    <a href=\"/\">← رجوع لمنصة غراس</a>\n    <button style=\"background:none;color:#CBD9EC;text-decoration:underline;margin-top:6px\" onclick=\"document.getElementById('winOv').classList.remove('show');closeGame()\">🌱 العودة للمولّد</button>`;\n  document.getElementById('winOv').classList.add('show');\n}\nfunction drawGame(){\n  SFX.pick();\n  document.getElementById('winOv').innerHTML=`\n    <div class=\"cup\">🤝</div>\n    <h1>تعادل!</h1>\n    <p style=\"color:#CBD9EC;font-weight:700\">امتلأت اللوحة بدون فائز — جربوا مرة ثانية 🌱</p>\n    <button onclick=\"document.getElementById('winOv').classList.remove('show');startPlay()\">🔄 العب مرة أخرى</button>\n    <a href=\"/\">← رجوع لمنصة غراس</a>\n    <button style=\"background:none;color:#CBD9EC;text-decoration:underline;margin-top:6px\" onclick=\"document.getElementById('winOv').classList.remove('show');closeGame()\">🌱 العودة للمولّد</button>`;\n  document.getElementById('winOv').classList.add('show');\n}\n\nfunction confetti(){\n  const colors=['#F3C64B','#7A9E7E','#FF7B6B','#5DADE2','#C084D4'];\n  for(let i=0;i<70;i++){const c=document.createElement('div');c.className='confetti';\n    c.style.cssText=`left:${Math.random()*100}vw;background:${colors[i%5]};animation-duration:${2+Math.random()*2.5}s;animation-delay:${Math.random()*1.2}s`;\n    document.body.appendChild(c);setTimeout(()=>c.remove(),5000);}\n}\ntry{updateCreditBadge();}catch(_){}\nwindow.addEventListener('load',()=>{try{loadSaved();}catch(_){}});\n\n/* ===== مكتبة ألعابي المحفوظة ===== */\n\n/* ===================== GHIRAS-LIBRARY : ألعابي المحفوظة ===================== */\n(function(){\n  const TYPE='xo';               // نوع اللعبة (يُستبدل عند البناء)\n  const LABEL='إكس أو';             // اسم اللعبة للعرض\n  const API='/api/saved-games';\n  const arNum=(n)=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n  window.__libCurId = window.__libCurId || null;\n\n  // ---------- بناء الواجهة ----------\n  const css=`\n  #libFab{position:fixed;bottom:18px;inset-inline-start:18px;z-index:900;display:inline-flex;align-items:center;gap:8px;\n    background:linear-gradient(180deg,#FFE9A8,#F0C24C);color:#5A3E00;font-weight:800;font-size:.95rem;font-family:inherit;\n    padding:12px 18px;border:none;border-radius:999px;box-shadow:0 8px 22px rgba(217,162,22,.4);cursor:pointer;transition:transform .15s}\n  #libFab:hover{transform:translateY(-2px) scale(1.03)}\n  #libFab .cnt{background:#fff;color:#B98900;border-radius:999px;min-width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.8rem;padding:0 6px}\n  #libBg{position:fixed;inset:0;background:rgba(18,24,40,.55);z-index:950;display:none;align-items:center;justify-content:center;padding:18px;backdrop-filter:blur(3px)}\n  #libBg.on{display:flex}\n  #libCard{background:#fff;border-radius:24px;max-width:560px;width:100%;max-height:82vh;display:flex;flex-direction:column;box-shadow:0 24px 60px rgba(0,0,0,.35);overflow:hidden;font-family:inherit;direction:rtl}\n  #libHead{background:linear-gradient(180deg,#FFF6DC,#FDE9B8);padding:18px 20px;display:flex;align-items:center;justify-content:space-between}\n  #libHead h3{margin:0;color:#5A3E00;font-size:1.15rem;font-weight:800}\n  #libHead .x{background:#fff;border:none;width:34px;height:34px;border-radius:50%;font-size:1.1rem;cursor:pointer;color:#8a6d1e;box-shadow:0 3px 8px rgba(0,0,0,.12)}\n  #libBody{padding:16px 18px;overflow:auto}\n  .libItem{display:flex;align-items:center;gap:12px;background:#F8FAFF;border:1.5px solid #E7EDF5;border-radius:16px;padding:12px 14px;margin-bottom:10px}\n  .libItem .ic{font-size:1.6rem}\n  .libItem .mid{flex:1;min-width:0}\n  .libItem .t{font-weight:800;color:#22314B;font-size:1rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .libItem .s{font-size:.78rem;color:#8794A6;font-weight:700;margin-top:2px}\n  .libItem .op{background:linear-gradient(180deg,#7FD79A,#49B96E);color:#fff;border:none;font-weight:800;font-family:inherit;\n    padding:9px 16px;border-radius:12px;cursor:pointer;font-size:.9rem;white-space:nowrap}\n  .libItem .dl{background:#fff;border:1.5px solid #F2C4C4;color:#D45B5B;width:38px;height:38px;border-radius:12px;cursor:pointer;font-size:1rem}\n  .libEmpty{text-align:center;color:#8794A6;font-weight:700;padding:34px 10px;line-height:1.9}\n  .libToast{position:fixed;bottom:78px;inset-inline-start:18px;z-index:980;background:#2E7D46;color:#fff;font-weight:800;\n    font-family:inherit;padding:11px 18px;border-radius:14px;box-shadow:0 8px 20px rgba(0,0,0,.25);opacity:0;transform:translateY(8px);transition:all .25s}\n  .libToast.on{opacity:1;transform:translateY(0)}\n  @media(max-width:520px){#libFab span.tx{display:none}}\n  `;\n  const st=document.createElement('style'); st.textContent=css; document.head.appendChild(st);\n\n  const fab=document.createElement('button'); fab.id='libFab';\n  fab.innerHTML=`📚 <span class=\"tx\">ألعابي المحفوظة</span> <span class=\"cnt\" id=\"libCnt\">٠</span>`;\n  fab.onclick=open;\n  const bg=document.createElement('div'); bg.id='libBg';\n  bg.innerHTML=`<div id=\"libCard\">\n     <div id=\"libHead\"><h3>📚 ألعابي المحفوظة — ${LABEL}</h3><button class=\"x\" onclick=\"GHLib.close()\">✕</button></div>\n     <div id=\"libBody\"><div class=\"libEmpty\">جارِ التحميل…</div></div>\n   </div>`;\n  bg.addEventListener('click',e=>{ if(e.target===bg) close(); });\n  function mount(){ if(!document.body){ return setTimeout(mount,50); } document.body.appendChild(fab); document.body.appendChild(bg); refreshCount(); }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',mount); else mount();\n\n  // ---------- شبكة ----------\n  async function jget(u){ const r=await fetch(u); if(!r.ok) throw new Error('http'); return r.json(); }\n  async function listGames(){ try{ const d=await jget(API+'?type='+TYPE); return d.games||[]; }catch(e){ return null; } }\n\n  let cache=[];\n  async function refreshCount(){ const g=await listGames(); if(g===null)return; cache=g; const c=document.getElementById('libCnt'); if(c)c.textContent=arNum(g.length); }\n\n  function open(){ bg.classList.add('on'); render(); }\n  function close(){ bg.classList.remove('on'); }\n\n  async function render(){\n    const body=document.getElementById('libBody');\n    body.innerHTML=`<div class=\"libEmpty\">جارِ التحميل…</div>`;\n    const g=await listGames();\n    if(g===null){ body.innerHTML=`<div class=\"libEmpty\">تعذّر الاتصال. تأكدي من تسجيل الدخول وحاولي مرة أخرى.</div>`; return; }\n    cache=g;\n    const c=document.getElementById('libCnt'); if(c)c.textContent=arNum(g.length);\n    if(!g.length){ body.innerHTML=`<div class=\"libEmpty\">ما عندك ألعاب محفوظة بعد 🌱<br>أنشئي لعبة وبتنحفظ هنا تلقائيًا لترجعي لها أي وقت.</div>`; return; }\n    body.innerHTML=g.map(it=>{\n      const dt=fmt(it.updated_at);\n      return `<div class=\"libItem\" data-id=\"${it.id}\">\n        <span class=\"ic\">${icon()}</span>\n        <div class=\"mid\"><div class=\"t\">${esc(it.title||'لعبة')}</div><div class=\"s\">آخر تحديث: ${dt}</div></div>\n        <button class=\"op\" onclick=\"GHLib.load('${it.id}')\">▶️ افتح</button>\n        <button class=\"dl\" title=\"حذف\" onclick=\"GHLib.del('${it.id}',event)\">🗑️</button>\n      </div>`;\n    }).join('');\n  }\n\n  function icon(){ return ({millionaire:'🏆',snake:'🎲',xo:'⭕',sinjim:'🧠'})[TYPE]||'🎮'; }\n  function esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\n  function fmt(iso){ try{ const d=new Date(iso); const D=arNum(d.getDate()), M=arNum(d.getMonth()+1), Y=arNum(d.getFullYear()); return `${D}/${M}/${Y}`; }catch(e){ return '—'; } }\n\n  function toast(msg){ const t=document.createElement('div'); t.className='libToast'; t.textContent=msg; document.body.appendChild(t);\n    requestAnimationFrame(()=>t.classList.add('on')); setTimeout(()=>{t.classList.remove('on'); setTimeout(()=>t.remove(),300);},2200); }\n\n  // ---------- حفظ تلقائي ----------\n  function newGame(){ window.__libCurId=null; }  // يُستدعى عند إنشاء لعبة جديدة\n\n  async function save(){\n    if(typeof window.__libGetData!=='function') return;\n    const g=window.__libGetData(); if(!g||!g.data) return;\n    try{\n      const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},\n        body:JSON.stringify({id:window.__libCurId||undefined, game_type:TYPE, title:g.title||'لعبة', data:g.data})});\n      const d=await r.json(); if(d&&d.id){ window.__libCurId=d.id; refreshCount(); }\n    }catch(e){}\n  }\n\n  // حفظ عند اللعب ثم بدء لعبة جديدة (يمنع الكتابة فوق اللعبة المدفوعة)\n  async function commitSave(){ await save(); newGame(); }\n\n  async function load(id){\n    const it=cache.find(x=>x.id===id); if(!it) return;\n    if(typeof window.__libApply==='function'){ try{ window.__libApply(it.data); }catch(e){} }\n    window.__libCurId=id; close(); toast('✅ فُتحت اللعبة — جاهزة للّعب');\n  }\n\n  async function del(id,ev){ if(ev)ev.stopPropagation();\n    try{ await fetch(API+'?id='+encodeURIComponent(id),{method:'DELETE'}); }catch(e){}\n    cache=cache.filter(x=>x.id!==id); render(); refreshCount();\n  }\n\n  window.GHLib={open,close,load,del,save,newGame,commitSave,refreshCount};\n})();\n";

export default async function XoPage() {
  const supabase = createServerSupabase();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect('/login?next=/xo');

  const { data: profile } = await supabase
    .from('profiles')
    .select('role, status, game_credits')
    .eq('id', user.id)
    .single();

  const isAdmin = profile?.role === 'admin';
  const credits = profile?.game_credits ?? 0;
  if (!isAdmin && profile?.status === 'suspended') redirect('/');
  if (!isAdmin && credits <= 0) redirect('/millionaire-locked');

  const boot = `window.__IS_ADMIN=${isAdmin ? 'true' : 'false'};window.__GAME_CREDITS=${isAdmin ? 9999 : credits};`;

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <div dangerouslySetInnerHTML={{ __html: BODY }} />
      <Script id="xo-boot" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: boot }} />
      <Script id="xo-main" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: JS }} />
    </>
  );
}
